SELECT CASE WHEN monthly_fee >= 259 THEN 'high' WHEN monthly_fee >= 91 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END AS end_cohort, MAX(monthly_fee) - MIN(monthly_fee) AS monthly_fee_range, ROUND((100 * SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cancelled FROM subscriptions WHERE monthly_fee >= 140 GROUP BY CASE WHEN monthly_fee >= 259 THEN 'high' WHEN monthly_fee >= 91 THEN 'mid' ELSE 'low' END, CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END
